/** Rows of a sheet as objects keyed by its header row (the first row containing all of \`must\`). */
function table(XLSX, wb, sheet, must) {
  const ws = wb.Sheets[sheet]; if (!ws) return [];
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: '' });
  const h = rows.findIndex(r => must.every(m => r.some(c => norm(c) === norm(m))));
  if (h < 0) return [];
  const head = rows[h].map(c => txt(c));
  return rows.slice(h + 1).filter(r => r.some(c => txt(c))).map(r => Object.fromEntries(head.map((k, i) => [k, r[i]])));
}
