ATL_SRC.push(['@atl/opmoves.js', 0, `// Reads the WMS scan export ("BetterDataGrid": Username, ActivityDate, SkidID, OldValue, NewValue, …) into
// put aways and picks per operator per day. Rules (set by Josh, Nov 2026):
//  - Each Skid ID is one move. The same Skid ID scanned to the same NewValue more than once is still one move
//    (the first scan counts — its operator and date).
//  - Only the date of ActivityDate matters, not the time.
//  - NewValue a rack location ending in -00 (23-12-00, 22-01-00, …) = a Pick (pulled down to the floor position).
//  - NewValue any other rack location (23-12-08, 22-04-10, …) = a Put Away — whether it came from a receiving /
//    staging location (TRSTG, RRSTG, TR_STG, RR_STG, 01-GENERAL) or from another rack location.
//  - NewValue that isn't a rack location (moved back to staging, quality hold, …) isn't counted; it is listed.
//  - An Activity other than "Location Move" isn't counted; it is listed.
// The operator's Username (MarioB, FSuarez) is matched to the Employees roster by its WMS Username, else by
// first name + last initial / first initial + last name.
import { store } from '@atl/store.js';
import { excelDate, parseLooseDate, isISO, norm } from '@atl/util.js';

const SHEETJS = 'https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs';
const txt = v => String(v ?? '').trim();
const letters = s => norm(s).replace(/[^A-Z]/g, '');
const RACK = /^\\d+-\\d+-\\d+$/;

/** 'pick' | 'putaway' | '' for a move's new location. */
export const moveType = to => (!RACK.test(txt(to)) ? '' : /-0+$/.test(txt(to)) ? 'pick' : 'putaway');

/** Activity date (Excel serial, Date or "11/2/2026 9:26 AM") → '2026-11-02'. */
function dateOf(v) {
  if (typeof v === 'number' || v instanceof Date) return excelDate(v);
  const s = txt(v);
  return parseLooseDate(s.split(/[ T]/)[0]) || (isISO(s.slice(0, 10)) ? s.slice(0, 10) : '');
}

/** Read one export → { file, scans: [{user, date, time, activity, skid, from, to}] } */
export async function readMoveFile(file) {
  const XLSX = await import(SHEETJS);
  const wb = XLSX.read(await file.arrayBuffer());
  for (const name of wb.SheetNames) {
    const rows = XLSX.utils.sheet_to_json(wb.Sheets[name], { header: 1, raw: true, defval: '' });
    const h = rows.findIndex(r => r.some(c => letters(c) === 'SKIDID') && r.some(c => letters(c) === 'NEWVALUE'));
    if (h < 0) continue; // e.g. a pivot sheet
    const head = rows[h].map(letters), col = n => head.indexOf(n);
    const cu = col('USERNAME'), cd = col('ACTIVITYDATE'), ca = col('ACTIVITY'), cs = col('SKIDID'), co = col('OLDVALUE'), cn = col('NEWVALUE');
    if (cu < 0 || cd < 0) throw new Error(\`\${file.name}: the Username / ActivityDate columns weren't found.\`);
    const scans = rows.slice(h + 1).filter(r => txt(r[cs]) && txt(r[cu])).map(r => ({
      user: txt(r[cu]), date: dateOf(r[cd]), time: typeof r[cd] === 'number' ? r[cd] : 0, activity: ca >= 0 ? txt(r[ca]) : '',
      skid: txt(r[cs]), from: co >= 0 ? norm(r[co]) : '', to: norm(r[cn]),
    }));
    return { file: file.name, scans };
  }
  throw new Error(\`\${file.name}: no sheet with SkidID and NewValue columns.\`);
}

/**
 * All dropped files together → moves per operator per day.
 * { days: [{user, date, putaway, pick}], dups, skipped: [{why, n}], total }
 */
export function tallyMoves(files) {
  const scans = files.flatMap(f => f.scans).sort((a, b) => a.date.localeCompare(b.date) || a.time - b.time);
  const seen = new Set(), days = new Map(), skipped = new Map();
  let dups = 0, total = 0;
  const skip = why => skipped.set(why, (skipped.get(why) || 0) + 1);
  for (const s of scans) {
    if (s.activity && norm(s.activity) !== 'LOCATION MOVE') { skip(\`activity “\${s.activity}”\`); continue; }
    if (!isISO(s.date)) { skip('no activity date'); continue; }
    const k = s.skid + '|' + s.to;
    if (seen.has(k)) { dups++; continue; }
    seen.add(k);
    const type = moveType(s.to);
    if (!type) { skip(\`moved to \${s.to || 'a blank location'}\`); continue; }
    const dk = s.user.toLowerCase() + '|' + s.date;
    const d = days.get(dk) || { user: s.user, date: s.date, putaway: 0, pick: 0 };
    d[type]++; total++; days.set(dk, d);
  }
  return { days: [...days.values()], dups, skipped: [...skipped.entries()].map(([why, n]) => ({ why, n })), total };
}

/** Name words, with "LAST, FIRST" turned round. */
const words = name => {
  let t = norm(name).replace(/[^A-Z, ]/g, ' ');
  if (t.includes(',')) { const [last, first] = t.split(','); t = \`\${first} \${last}\`; }
  return t.split(/\\s+/).filter(Boolean);
};

/** The roster employee behind a WMS Username, or null when there's none (or more than one fits). */
export function matchOperator(user, emps = store.rows('employees')) {
  const u = letters(user);
  if (!u) return null;
  const set = emps.filter(e => letters(e.wmsUser) === u);
  if (set.length === 1) return set[0];
  const fits = e => [e.name, e.laborName].filter(Boolean).some(n => {
    const w = words(n), first = w[0] || '';
    return w.slice(1).some(last => [first + last[0], first[0] + last, first + last].includes(u));
  });
  for (const pool of [emps.filter(e => norm(e.rosterStatus) === 'ACTIVE'), emps]) {
    const hit = [...new Set(pool.filter(fits))];
    if (hit.length === 1) return hit[0];
    if (hit.length > 1) return null;
  }
  return null;
}

/** How an operator is written in the Operator Moves log: their labor name, else their roster name. */
export const operatorName = e => (e ? e.laborName || e.name : '');`]);
